function renderMetricInputs(registry: readonly CollectorEntry[]): string { const descriptions = new Map<string, string[]>(); for (const { metric, collector } of registry) { for (const input of collector.inputs) { if (CORE_INPUTS.includes(input.name)) { throw new Error(`metrics/${metric.name}: the input "${input.name}" is already an input of the Action.`); } descriptions.set(input.name, [...(descriptions.get(input.name) ?? []), describeInput(metric.name, input)]); } } return [...descriptions].map(([name, parts]) => ` ${name}:
 description: ${JSON.stringify(parts.join(' '))}
 required: false
`).join(''); }

